-- Complete local Supabase only. Synthetic identities and all mutations roll back.
begin;
create function pg_temp.c2_id(n int) returns uuid language sql as $$ select ('e0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid; $$;
create function pg_temp.c2_actor(n int) returns void language sql as $$ select set_config('request.jwt.claim.sub',pg_temp.c2_id(n)::text,true); $$;
create function pg_temp.c2_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'C2 FAIL: %',label; end if; end; $$;
create function pg_temp.c2_error(sql text,code text) returns void language plpgsql as $$ begin begin execute sql; exception when others then if sqlstate=code then return; end if; raise; end; raise exception 'C2 expected %',code; end; $$;
create function pg_temp.c2_cmd(cmd text,payload jsonb) returns jsonb language sql as $$ select public.passport_command(cmd,payload,gen_random_uuid()); $$;
create function pg_temp.c2_keep(key text,val jsonb) returns void language sql as $$ select set_config('passport.c2.'||key,val->>'id',true); $$;
create function pg_temp.c2_ref(key text) returns uuid language sql as $$ select current_setting('passport.c2.'||key)::uuid; $$;
create function pg_temp.c2_worker(action text,payload jsonb) returns jsonb language sql as $$ select public.passport_stream_worker(action,payload||jsonb_build_object('account_id',repeat('a',32))); $$;
create function pg_temp.c2_reserve(key uuid) returns jsonb language sql as $$ select public.passport_stream_reserve(pg_temp.c2_ref('order'),key,12000,'video/quicktime',repeat('f',64)); $$;
insert into auth.users(id) select pg_temp.c2_id(i) from generate_series(1,4) i;
insert into public.coaches(id,name,is_approved) values(pg_temp.c2_id(9),'Synthetic C2 coach',true);
insert into public.coach_memberships(coach_id,user_id) values(pg_temp.c2_id(9),pg_temp.c2_id(3));
insert into public.admin_memberships(user_id,role,status) values(pg_temp.c2_id(1),'owner','active');
set local role authenticated;
select pg_temp.c2_actor(2);
select pg_temp.c2_error($q$select public.passport_stream_reserve(pg_temp.c2_id(20),pg_temp.c2_id(21),12000,'video/mp4',repeat('f',64))$q$,'42501');
select pg_temp.c2_error($q$select public.passport_stream_worker('list','{}')$q$,'42501');
select pg_temp.c2_error($q$select * from private.pp_stream_sessions$q$,'42501');
reset role;
update private.pp_runtime set enabled=true;
set local role authenticated;
select pg_temp.c2_actor(1);
select pg_temp.c2_cmd('publish_standard','{"id":"a0000000-0000-4000-8000-000000000002","reason":"Synthetic C2 rubric approval"}');
select pg_temp.c2_cmd('publish_policy','{"id":"c0000000-0000-4000-8000-000000000001","reason":"Synthetic C2 policy approval"}');
select pg_temp.c2_keep('grant',pg_temp.c2_cmd('set_assessor',jsonb_build_object('coach_id',pg_temp.c2_id(9),'assessor_user_id',pg_temp.c2_id(3),'skill_id','improver-bandeja','credential_reference','mock:c2','status','approved','credentials_verified',true,'reason','Synthetic assessor credential check')));
select pg_temp.c2_actor(3);
select pg_temp.c2_keep('offer',pg_temp.c2_cmd('create_offer',jsonb_build_object('grant_id',pg_temp.c2_ref('grant'),'standard_id','a0000000-0000-4000-8000-000000000002','price_minor',3500,'currency','GBP')));
select pg_temp.c2_actor(2);
select pg_temp.c2_keep('order',pg_temp.c2_cmd('create_order',jsonb_build_object('offer_id',pg_temp.c2_ref('offer'),'policy_id','c0000000-0000-4000-8000-000000000001')));
select pg_temp.c2_error($q$select pg_temp.c2_reserve(pg_temp.c2_id(22))$q$,'23514');
reset role; set local role service_role;
select public.passport_provider_event('payment','c2:payment',jsonb_build_object('order_id',pg_temp.c2_ref('order'),'amount_minor',3500,'currency','GBP','payment_reference','mock:c2:funding'));
select pg_temp.c2_error($q$insert into private.pp_stream_sessions(id) values(gen_random_uuid())$q$,'42501');
reset role; set local role authenticated;
select pg_temp.c2_actor(4);
select pg_temp.c2_error($q$select pg_temp.c2_reserve(pg_temp.c2_id(22))$q$,'42501');
select pg_temp.c2_actor(2);
select pg_temp.c2_keep('session',pg_temp.c2_reserve(pg_temp.c2_id(22)));
select pg_temp.c2_assert((pg_temp.c2_reserve(pg_temp.c2_id(22))->>'id')::uuid=pg_temp.c2_ref('session'),'same request returns same reservation');
select pg_temp.c2_assert((pg_temp.c2_reserve(pg_temp.c2_id(23))->>'id')::uuid=pg_temp.c2_ref('session'),'different request does not allocate a second live upload');
select pg_temp.c2_error($q$select public.passport_stream_reserve(pg_temp.c2_ref('order'),pg_temp.c2_id(24),12000,'video/mp4',repeat('d',64))$q$,'23514');
reset role; set local role service_role;
select pg_temp.c2_assert((pg_temp.c2_worker('claim',jsonb_build_object('id',pg_temp.c2_ref('session'),'max_bytes',52428800))->>'claimed')::boolean,'only one worker claims creation');
select pg_temp.c2_assert(not (pg_temp.c2_worker('claim',jsonb_build_object('id',pg_temp.c2_ref('session'),'max_bytes',52428800))->>'claimed')::boolean,'second worker cannot create');
select pg_temp.c2_worker('bind',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('b',32),'ciphertext','synthetic-encrypted-capability'));
select pg_temp.c2_error($q$select pg_temp.c2_worker('get',jsonb_build_object('uid',repeat('c',32)))$q$,'42501');
select pg_temp.c2_error($q$select pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('c',32),'stage','ready','duration',80,'bytes',12000))$q$,'42501');
select pg_temp.c2_error($q$select pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('b',32),'stage','ready','duration',91,'bytes',12000))$q$,'23514');
select pg_temp.c2_error($q$select pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('b',32),'stage','ready','duration',80,'bytes',12001))$q$,'23514');
select pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('b',32),'stage','ready','duration',80,'bytes',12000));
select pg_temp.c2_assert((pg_temp.c2_worker('list','{}')->0->>'category')='awaiting_review','retention cannot treat a pending professional review as unfinished footage');
select pg_temp.c2_assert(jsonb_array_length(pg_temp.c2_worker('for_player',jsonb_build_object('player_id',pg_temp.c2_id(2))))=1,'erasure lookup is limited to the selected player and configured provider account');
select pg_temp.c2_assert((pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('session'),'uid',repeat('b',32),'stage','failed'))->>'ignored')::boolean,'late failure cannot reopen ready evidence');
reset role; set local role authenticated;
select pg_temp.c2_actor(2);
select pg_temp.c2_assert((select state='ready_for_review' and review_due_at is not null and payment_reference='mock:c2:funding' from public.pp_orders where id=pg_temp.c2_ref('order')),'valid funded footage starts review target');
select pg_temp.c2_actor(3);
select pg_temp.c2_assert((select count(*)=1 from public.pp_submission_attempts where order_id=pg_temp.c2_ref('order')),'assigned assessor can read own evidence');
select pg_temp.c2_actor(1);
select pg_temp.c2_cmd('set_assessor',jsonb_build_object('id',pg_temp.c2_ref('grant'),'status','suspended','reason','Synthetic permission revocation test'));
select pg_temp.c2_actor(3);
select pg_temp.c2_assert((select count(*)=0 from public.pp_submission_attempts where order_id=pg_temp.c2_ref('order')),'suspended assessor loses evidence access');
select pg_temp.c2_actor(1);
select pg_temp.c2_cmd('set_assessor',jsonb_build_object('id',pg_temp.c2_ref('grant'),'status','approved','credentials_verified',true,'reason','Synthetic permission reapproval test'));
select pg_temp.c2_actor(3);
select pg_temp.c2_cmd('submit_review',jsonb_build_object('order_id',pg_temp.c2_ref('order'),'outcome','replacement_requested','observations','Synthetic poor framing example.','replacement_reason','Contact was outside the frame.','recording_guidance','Include full body and racket contact.'));
select pg_temp.c2_actor(2);
select pg_temp.c2_keep('replacement',pg_temp.c2_reserve(pg_temp.c2_id(25)));
select pg_temp.c2_assert(pg_temp.c2_ref('replacement')<>pg_temp.c2_ref('session'),'replacement has a new session under the same order');
select pg_temp.c2_assert((select count(*)=2 from public.pp_submission_attempts where order_id=pg_temp.c2_ref('order')),'replacement creates attempt two, not another paid order');
reset role; set local role service_role;
select pg_temp.c2_worker('claim',jsonb_build_object('id',pg_temp.c2_ref('replacement'),'max_bytes',52428800));
select pg_temp.c2_worker('bind',jsonb_build_object('id',pg_temp.c2_ref('replacement'),'uid',repeat('c',32),'ciphertext','synthetic-encrypted-replacement'));
select pg_temp.c2_worker('reconcile',jsonb_build_object('id',pg_temp.c2_ref('replacement'),'uid',repeat('c',32),'stage','ready','duration',80,'bytes',12000));
reset role; set local role authenticated;
select pg_temp.c2_actor(3);
select pg_temp.c2_cmd('submit_review',jsonb_build_object('order_id',pg_temp.c2_ref('order'),'outcome','developing','observations','Synthetic developing review.','positive_feedback','Good preparation.','areas_for_improvement','Control contact.','practice_tasks',jsonb_build_array('Controlled feeds'),'next_step','Repeat practice.','criteria_results',jsonb_build_object('position',true,'contact',false)));
select pg_temp.c2_actor(2);
select pg_temp.c2_assert((select state='completed' and payment_state='paid' from public.pp_orders where id=pg_temp.c2_ref('order')),'Developing is delivered under the original funding');
select pg_temp.c2_keep('reassessment',pg_temp.c2_cmd('create_order',jsonb_build_object('offer_id',pg_temp.c2_ref('offer'),'policy_id','c0000000-0000-4000-8000-000000000001','parent_order_id',pg_temp.c2_ref('order'))));
select pg_temp.c2_error($q$select public.passport_stream_reserve(pg_temp.c2_ref('reassessment'),pg_temp.c2_id(26),12000,'video/mp4',repeat('f',64))$q$,'23514');
reset role; set local role service_role;
select pg_temp.c2_worker('queue_delete',jsonb_build_object('id',pg_temp.c2_ref('replacement'),'reason','Synthetic explicitly approved deletion test.'));
select pg_temp.c2_worker('deleted',jsonb_build_object('id',pg_temp.c2_ref('replacement')));
select pg_temp.c2_worker('deleted',jsonb_build_object('id',pg_temp.c2_ref('replacement')));
reset role;
select pg_temp.c2_assert((select count(*)=2 from public.pp_reviews where order_id=pg_temp.c2_ref('order')),'deletion preserves review and replacement history');
select pg_temp.c2_assert((select count(*)=0 from public.pp_skill_verifications where order_id=pg_temp.c2_ref('order')),'Developing is not a Verified milestone');
rollback;
